===== HouseholdSize.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Counts the members of an owner's household: the owners sharing this owner's last name and address,
 * compared case-insensitively with collapsed whitespace (the same grouping
 * {@link HouseholdId} groups them by). The owner itself is included, so a freshly created
 * owner counts towards its own household total.
 */
public final class HouseholdSize {

    private HouseholdSize() {
    }

    public static int of(Owner owner, OwnerRepository repository) {
        String lastName = normalize(owner.getLastName());
        String address = normalize(owner.getAddress());
        int count = 0;
        for (Owner other : repository.findAll()) {
            if (lastName.equals(normalize(other.getLastName()))
                    && address.equals(normalize(other.getAddress()))) {
                count++;
            }
        }
        return count;
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

===== IdentityKey.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey}: the single value duplicate detection is expressed
 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
 * telephone is E.164 (see {@link E164Telephone}), the email is lower-cased (empty when absent) and
 * the household id groups owners by last name and address (see {@link HouseholdId}). Because the
 * telephone is part of the key, two members of one household with different telephones have
 * different keys and are both allowed; only owners that collide on the key are duplicates.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        return telephone(owner) + '|' + email(owner) + '|' + HouseholdId.of(owner);
    }

    static String telephone(Owner owner) {
        String telephone = E164Telephone.toE164(owner.getTelephone());
        return telephone == null ? "" : telephone;
    }

    static String email(Owner owner) {
        String email = owner.getEmail();
        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
    }
}

===== MembershipLevel.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's numeric membership level from 1 to 3: starts at 1, adds 1 when an email is
 * present, adds 1 when {@code namesakeCount} is 0, and is capped at 3 (level 4 is reserved for
 * tenure).
 */
public final class MembershipLevel {

    private MembershipLevel() {
    }

    public static int of(Owner owner, int namesakeCount) {
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            level++;
        }
        if (namesakeCount == 0) {
            level++;
        }
        return Math.min(level, 3);
    }
}

