package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's membership tier: {@code GOLD} for a household of 3 or more members, else
 * {@code SILVER} for an owner with an email and no namesakes ({@code namesakeCount} of 0), otherwise
 * {@code BRONZE}.
 */
public final class MembershipTier {

    private MembershipTier() {
    }

    public static String of(Owner owner, int namesakeCount, int householdSize) {
        if (householdSize >= 3) {
            return "GOLD";
        }
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return namesakeCount == 0 && hasEmail ? "SILVER" : "BRONZE";
    }
}

===== PossibleDuplicate.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Finds the existing owner this owner is a possible (soft) duplicate of: another owner sharing this
 * owner's last name (case-insensitive) and postcode but with a different telephone. A shared last
 * name and postcode with a matching telephone would be a hard duplicate (rejected at create, see
 * {@link RejectDuplicateOwnerIdentity}), so a differing telephone is exactly the soft-match case.
 * Owners without a postcode never soft-match. Returns the matching owner's id (the lowest when
 * several match), or {@code null} when there is no possible duplicate.
 */
public final class PossibleDuplicate {

    private PossibleDuplicate() {
    }

    public static Integer of(Owner owner, OwnerRepository repository) {
        String postcode = owner.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        Integer match = null;
        for (Owner other : repository.findAll()) {
            if (!Objects.equals(other.getId(), owner.getId()) && postcode.equals(other.getPostcode())
                    && equalsIgnoreCase(owner.getLastName(), other.getLastName())
                    && !Objects.equals(owner.getTelephone(), other.getTelephone())
                    && (match == null || other.getId() < match)) {
                match = other.getId();
            }
        }
        return match;
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

===== RejectDuplicateOwnerIdentity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;

/**
 * Rejects 409 when the built owner shares another owner's {@link IdentityKey}. This one check
 * replaces the former separate telephone, email and household duplicate checks: an owner collides
 * only on an exact match of the telephone-and-email identity, so two members of one household with
 * different telephones (or different emails) are both allowed.
 */
public class RejectDuplicateOwnerIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateOwnerIdentityException {
        String telephone = IdentityKey.telephone(owner);
        String email = IdentityKey.email(owner);
        for (Owner other : ownerRepository.findAll()) {
            if (other != owner && telephone.equals(IdentityKey.telephone(other))
                    && email.equals(IdentityKey.email(other))) {
                throw new DuplicateOwnerIdentityException(IdentityKey.of(owner));
            }
        }
    }
}

===== AssignOwnerCustomerCode.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code customerCode} formatted {@code <REGION>-<HASH8>}: REGION is the region
 * code derived from the postcode (see {@link Locality}), and HASH8 is the first 8 upper-case hex
 * characters of SHA-256 over the normalized telephone followed by the last name (e.g.
 * 'NSW-1A2B3C4D'). Every value derived downstream — the membership number and its check digit, the
 * create audit record, and the locality — reads this identity.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner) {
        owner.setCustomerCode(Locality.of(owner) + "-" + hash8(owner));
    }

    private static String hash8(Owner owner) {
        String key = owner.getTelephone() + owner.getLastName();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder hash = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                hash.append(String.format("%02X", digest[i]));
            }
            return hash.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}

===== NormalizeOwnerAddress.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;
import java.util.Locale;
import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;

/**
 * Rewrites the built owner's address into a canonical form in place, so later steps save, compare
 * (household duplicate detection and the shared household id) and return it as {@code address}. The
 * value is trimmed, its internal whitespace collapsed, upper-cased and common street-type
 * abbreviations expanded (ST->STREET, RD->ROAD, AVE->AVENUE). An address that is blank after
 * normalization is rejected 400 via {@link MissingOwnerFieldsException}.
 */
public class NormalizeOwnerAddress {

    private static final Map<String, String> ABBREVIATIONS = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
        String address = owner.getAddress() == null ? "" : owner.getAddress().trim();
        if (address.isEmpty()) {
            throw new MissingOwnerFieldsException(List.of("address"));
        }
        StringBuilder normalized = new StringBuilder();
        for (String token : address.split("\\s+")) {
            String upper = token.toUpperCase(Locale.ROOT);
            if (normalized.length() > 0) {
                normalized.append(' ');
            }
            normalized.append(ABBREVIATIONS.getOrDefault(upper, upper));
        }
        owner.setAddress(normalized.toString());
    }
}

